import type { z } from "zod";

/**
 * Cross-section invariants for `cr-summary.template.md`.
 *
 * Rules enforced here:
 *
 * 1. **No broken cross-refs at merge** — Cross-reference health table MUST
 *    have `broken: 0`. Any non-zero broken count is a hard error.
 * 2. **validate-md status pass** — Validation results MUST show
 *    `validate-md status: pass`; CR is not summary-clean otherwise.
 * 3. **Base != head** — Generated by section's base commit MUST differ
 *    from head commit (zero-length CR is meaningless).
 * 4. **CR ID matches plan ID** — title CR number must equal Plan file's
 *    leading number.
 */

export const refine = (doc: unknown, ctx: z.core.$RefinementCtx): void => {
  const d = doc as Record<string, unknown>;

  // Rule 1: broken count == 0.
  const xref = (d["crossReferenceHealth"] ?? []) as Array<
    Record<string, string>
  >;
  const brokenRow = xref.find((r) => r["Status"] === "broken");
  if (brokenRow) {
    const count = parseInt(brokenRow["Count"] ?? "0", 10);
    if (count > 0) {
      ctx.addIssue({
        code: "custom",
        path: ["cross-reference-health"],
        message: `Cross-reference health shows ${count} broken link(s); merge gate requires zero.`,
      });
    }
  }

  // Rule 2: validate-md pass.
  const validation = (d["validationResults"] ?? {}) as Record<string, string>;
  const vmStatus = (validation["validate-md status"] ?? "").trim();
  if (vmStatus !== "pass") {
    ctx.addIssue({
      code: "custom",
      path: ["validation-results"],
      message: `validate-md status is "${vmStatus}"; merge gate requires "pass".`,
    });
  }

  // Rule 3: base != head.
  const generatedBy = (d["generatedBy"] ?? {}) as Record<string, string>;
  const base = (generatedBy["Base commit"] ?? "").trim();
  const head = (generatedBy["Head commit"] ?? "").trim();
  if (base && head && base === head) {
    ctx.addIssue({
      code: "custom",
      path: ["generated-by"],
      message: "Base commit equals Head commit — zero-length CR is invalid.",
    });
  }

  // Rule 4: CR id consistency between title and Plan file.
  const title = (d["title"] ?? "") as string;
  const titleMatch = /^CR-(\d{2,4})\b/.exec(title);
  const sourceCr = (d["sourceCr"] ?? {}) as Record<string, string>;
  const planFile = (sourceCr["Plan file"] ?? "").trim();
  const planMatch = /\/(\d{2,4})\.cr-plan\.md$/.exec(planFile);
  if (titleMatch && planMatch && titleMatch[1] !== planMatch[1]) {
    ctx.addIssue({
      code: "custom",
      path: ["source-cr", "Plan file"],
      message: `CR id in title ("${titleMatch[1]}") does not match Plan file id ("${planMatch[1]}").`,
    });
  }
};
